UPDATE academy.challenges SET hint_1 = $h$JWT (токен входа из трёх частей: header, payload, signature). Если сервер не проверяет подпись, в header можно поставить alg=none — подпись отключается, и данные токена меняются руками.$h$ WHERE slug = 'jwt-alg-none';
UPDATE academy.challenges SET hint_1 = $h$JWT HS256 (подпись токена секретом). Секрет здесь короткий и словарный — его можно подобрать как пароль.$h$ WHERE slug = 'jwt-weak-secret';
UPDATE academy.challenges SET hint_1 = $h$SQL-инъекция (вставка SQL-кода в поле формы). Запрос склеивается строкой, поэтому кавычка ' и комментарий -- меняют логику входа.$h$ WHERE slug = 'sqli-auth-bypass';
UPDATE academy.challenges SET hint_1 = $h$Mass Assignment (сервер сохраняет лишние поля из запроса). Если нет списка разрешённых полей, можно самому прислать role=admin.$h$ WHERE slug = 'mass-assignment-role';
UPDATE academy.challenges SET hint_1 = $h$Brute Force (перебор пароля). Сервер не ограничивает число попыток, а пароль admin есть в словаре.$h$ WHERE slug = 'brute-force-login';
UPDATE academy.challenges SET hint_1 = $h$Open Redirect (редирект на чужой сайт). Параметр next не проверяется, поэтому адрес можно заменить на внешний.$h$ WHERE slug = 'open-redirect-login';
UPDATE academy.challenges SET hint_1 = $h$Password Reset Poisoning (подмена домена в ссылке сброса пароля). Сервер собирает ссылку из заголовка Host и верит ему.$h$ WHERE slug = 'password-reset-poisoning';
UPDATE academy.challenges SET hint_1 = $h$GraphQL Introspection (запрос описания схемы). GraphQL сам рассказывает, какие типы и скрытые запросы у него есть.$h$ WHERE slug = 'graphql-introspection';
UPDATE academy.challenges SET hint_1 = $h$GraphQL Batching (много операций в одном запросе). Шлюз принимает массив запросов и не ограничивает его размер.$h$ WHERE slug = 'graphql-batching-dos';
UPDATE academy.challenges SET hint_1 = $h$Prototype Pollution (подмена общей «базы» полей JavaScript-объектов). Ключ __proto__ меняет поведение всех объектов в процессе.$h$ WHERE slug = 'prototype-pollution';
UPDATE academy.challenges SET hint_1 = $h$SSRF (сервер делает запрос по вашему URL). Так изнутри можно достучаться до сервисов, закрытых снаружи.$h$ WHERE slug = 'ssrf-image-fetch';
UPDATE academy.challenges SET hint_1 = $h$CORS (правила, какие сайты могут читать ответы API). Если разрешён любой Origin и cookies, чужой сайт прочитает данные пользователя.$h$ WHERE slug = 'cors-wildcard-credentials';
UPDATE academy.challenges SET hint_1 = $h$IDOR (доступ к чужому объекту по его id). Сервер находит заказ по номеру, но не проверяет, ваш ли он.$h$ WHERE slug = 'graphql-idor';
UPDATE academy.challenges SET hint_1 = $h$LFI (подключение чужого локального файла). Параметр page попадает в include без проверки пути.$h$ WHERE slug = 'legacy-lfi';
UPDATE academy.challenges SET hint_1 = $h$RFI (подключение файла по URL). include выполняет удалённый или data:// контент как PHP-код.$h$ WHERE slug = 'legacy-rfi';
UPDATE academy.challenges SET hint_1 = $h$XXE (внешняя сущность XML). XML-документ может попросить парсер прочитать локальный файл и вставить его в ответ.$h$ WHERE slug = 'legacy-xxe';
UPDATE academy.challenges SET hint_1 = $h$Command Injection (ввод попадает в системную команду). Символ ; запускает вторую команду после ping.$h$ WHERE slug = 'legacy-command-injection';
UPDATE academy.challenges SET hint_1 = $h$PHP Object Injection (подмена сериализованного объекта). unserialize собирает объект из cookie, а __destruct выполняет действие.$h$ WHERE slug = 'legacy-php-object-injection';
UPDATE academy.challenges SET hint_1 = $h$Unrestricted File Upload (загрузка исполняемого файла). Проверки расширения нет, а папка uploads исполняет PHP.$h$ WHERE slug = 'legacy-upload-php';
UPDATE academy.challenges SET hint_1 = $h$IDOR (заказ по id без проверки владельца). API отдаёт заказ, потому что нашёл его по номеру.$h$ WHERE slug = 'inventory-idor';
UPDATE academy.challenges SET hint_1 = $h$Race Condition (гонка запросов). Проверка баланса и списание не атомарны, поэтому параллельные запросы читают старый баланс.$h$ WHERE slug = 'inventory-race-condition';
UPDATE academy.challenges SET hint_1 = $h$Path Traversal (выход из папки через ../). Сервер читает файл по склеенному пути и не проверяет границы каталога.$h$ WHERE slug = 'inventory-path-traversal';
UPDATE academy.challenges SET hint_1 = $h$NoSQL Injection (объект-оператор вместо строки). В MongoDB $ne означает «не равно», и условие входа становится всегда истинным.$h$ WHERE slug = 'nosql-auth-bypass';
UPDATE academy.challenges SET hint_1 = $h$Blind NoSQL Injection (угадывание пароля по ответам). Оператор $regex проверяет префикс, а успех/ошибка работает как оракул.$h$ WHERE slug = 'nosql-blind';
UPDATE academy.challenges SET hint_1 = $h$DOM XSS (выполнение скрипта в браузере). Параметр q вставляется в HTML без экранирования.$h$ WHERE slug = 'dom-xss';
UPDATE academy.challenges SET hint_1 = $h$CSRF (запрос от имени пользователя с чужого сайта). Браузер сам отправляет cookie, а токена подтверждения нет.$h$ WHERE slug = 'csrf-profile-change';
UPDATE academy.challenges SET hint_1 = $h$Clickjacking (невидимый iframe). Страница не запрещает встраивание, поэтому кнопку можно наложить на чужой интерфейс.$h$ WHERE slug = 'clickjacking-checkout';
UPDATE academy.challenges SET hint_1 = $h$postMessage XSS (чужое окно присылает HTML с кодом). Обработчик вставляет event.data в innerHTML без проверки source.$h$ WHERE slug = 'postmessage-xss';
UPDATE academy.challenges SET hint_1 = $h$Session Fixation (навязанный id сессии). Сервер принимает sid из URL и не меняет его после входа.$h$ WHERE slug = 'session-fixation';
UPDATE academy.challenges SET hint_1 = $h$Cache Poisoning (подмена ответа в кэше). Кэш хранит ответ по пути, но тело зависит от заголовка X-Forwarded-Host.$h$ WHERE slug = 'cache-poisoning';